package com.aistock.notification.inbox;
import com.aistock.common.BusinessException;
import com.aistock.notification.alert.*;
import com.fasterxml.jackson.databind.*;
import java.time.*;import java.util.*;
import org.junit.jupiter.api.*;import org.springframework.jdbc.core.*;import org.springframework.jdbc.datasource.DriverManagerDataSource;import org.flywaydb.core.Flyway;
import static org.junit.jupiter.api.Assertions.*;
@Tag("mysql") class InboxMysqlTest {
 JdbcTemplate db; InboxService service; UUID owner=UUID.randomUUID(),other=UUID.randomUUID(),rule=UUID.randomUUID();
 ObjectMapper mapper=new ObjectMapper().findAndRegisterModules(); Instant now=Instant.parse("2026-10-10T12:00:00Z");
 @BeforeEach void setup(){String url=System.getenv("MAIL_TEST_DB_URL"),pw=System.getenv("MAIL_TEST_DB_PASSWORD");if(!"jdbc:mysql://127.0.0.1:13316/stock_notification_test?serverTimezone=UTC".equals(url)||pw==null)throw new IllegalStateException("isolated DB required");db=new JdbcTemplate(new DriverManagerDataSource(url,"root",pw));Flyway.configure().dataSource(db.getDataSource()).load().migrate();service=new InboxService(db,mapper,Clock.fixed(now,ZoneOffset.UTC));}
 UUID message(UUID user,UUID ruleId,Instant at)throws Exception{var e=mapper.readValue(getClass().getResourceAsStream("/alert/evidence.json"),AlertEvidenceClient.Evidence.class);UUID trigger=UUID.randomUUID(),id=UUID.randomUUID();var s=new AlertEvaluationRecords.Snapshot(ruleId,user,"SH600030",0,"PRICE_ABOVE","25.90",e.tradeDate(),e,at);db.update("insert into alert_trigger values(?,?,?,?,?,?,?,?)",trigger.toString(),user.toString(),"SH600030",ruleId.toString(),e.tradeDate(),0,mapper.writeValueAsString(s),java.sql.Timestamp.from(at));db.update("insert into inbox_message values(?,?,?,?,null)",id.toString(),trigger.toString(),user.toString(),java.sql.Timestamp.from(at));return id;}
 @Test void listsOnlyOwnerWithStableDescendingPaginationAndUnreadCounts()throws Exception{UUID a=message(owner,rule,now.minusSeconds(1)),b=message(owner,UUID.randomUUID(),now);message(other,UUID.randomUUID(),now);var p=service.list(owner,1,1,false);assertEquals(2,p.total());assertEquals(2,p.unreadCount());assertEquals(b,p.items().get(0).id());assertEquals(a,service.list(owner,2,1,false).items().get(0).id());service.read(owner,b);assertEquals(1,service.list(owner,1,20,true).total());assertEquals(1,service.unreadCount(owner).unreadCount());}
 @Test void firstReadTimeIsPreservedAndOtherOwnersCannotRead()throws Exception{UUID id=message(owner,rule,now);var first=service.read(owner,id);var later=new InboxService(db,mapper,Clock.fixed(now.plusSeconds(60),ZoneOffset.UTC));assertEquals(first.readAt(),later.read(owner,id).readAt());assertEquals("RESOURCE_NOT_FOUND",assertThrows(BusinessException.class,()->service.read(other,id)).code());}
 @Test void mixedBatchRollsBackAndValidBatchIsIdempotent()throws Exception{UUID a=message(owner,rule,now),b=message(other,UUID.randomUUID(),now);assertThrows(BusinessException.class,()->service.readBatch(owner,List.of(a,b)));assertEquals(1,service.unreadCount(owner).unreadCount());assertThrows(BusinessException.class,()->service.readBatch(owner,List.of(a,UUID.randomUUID())));assertEquals(1,service.unreadCount(owner).unreadCount());service.readBatch(owner,List.of(a));service.readBatch(owner,List.of(a));assertEquals(0,service.unreadCount(owner).unreadCount());}
 @Test void fixedClockEvaluationToInboxChainPreservesBoundariesAndSnapshots()throws Exception{var evidence=mapper.readValue(getClass().getResourceAsStream("/alert/evidence.json"),AlertEvidenceClient.Evidence.class);var clock=Clock.fixed(now,ZoneOffset.UTC);var repository=new AlertRuleRepository(db);var market=org.mockito.Mockito.mock(AlertEvidenceClient.class);var accounts=org.mockito.Mockito.mock(AlertMailAccountClient.class);var before=new AlertRecords.Boundary("SH600030","baostock",evidence.rawVersionId(),evidence.tradeDate().minusDays(1),evidence.tradeDate().minusDays(1),evidence.tradeDate().minusDays(1),"a".repeat(64),now,"alert-boundary-v1");var current=new AlertRecords.Boundary("SH600030","baostock",evidence.rawVersionId(),evidence.tradeDate(),evidence.tradeDate(),evidence.tradeDate(),"a".repeat(64),now,"alert-boundary-v1");var rules=new AlertRuleService(repository,id->before,clock,50);var rule=rules.create(owner,new AlertRecords.Create(UUID.randomUUID(),"SH600030","PRICE_ABOVE","25.90"));org.mockito.Mockito.when(market.read(evidence.id())).thenReturn(evidence);org.mockito.Mockito.when(market.boundary("SH600030")).thenReturn(current);org.mockito.Mockito.when(accounts.context(owner)).thenReturn(new AlertMailAccountClient.AccountContext(owner,"ENABLED",7,true,now));var evaluation=new AlertEvaluationService(repository,market,accounts,new com.aistock.notification.alertmail.AlertMailOutbox(new com.aistock.notification.alertmail.AlertMailRepository(db),false,java.time.Duration.ofHours(24)),clock);var request=new AlertEvaluationRecords.EvaluateRequest(UUID.randomUUID(),rule.id(),0,evidence.id(),now.plusSeconds(90));var first=evaluation.evaluate(request);assertEquals("TRIGGERED",first.state());assertEquals(first,evaluation.evaluate(request));assertEquals("ALREADY_TRIGGERED",evaluation.evaluate(new AlertEvaluationRecords.EvaluateRequest(UUID.randomUUID(),rule.id(),0,evidence.id(),now.plusSeconds(90))).state());var restarted=new InboxService(db,mapper,clock);assertEquals(1,restarted.list(owner,1,20,false).total());var message=restarted.list(owner,1,20,false).items().get(0);assertEquals(rule.threshold(),message.threshold());assertThrows(BusinessException.class,()->restarted.read(other,message.id()));var read=restarted.read(owner,message.id());assertEquals(read.readAt(),restarted.read(owner,message.id()).readAt());var off=rules.patch(owner,rule.id(),new AlertRecords.Patch(0L,null,null,false));assertEquals("SKIPPED_RULE_CHANGED",evaluation.evaluate(new AlertEvaluationRecords.EvaluateRequest(UUID.randomUUID(),off.id(),0,evidence.id(),now.plusSeconds(90))).state());var equal=rules.create(owner,new AlertRecords.Create(UUID.randomUUID(),"SH600030","PRICE_ABOVE","25.91"));assertEquals("NOT_MET",evaluation.evaluate(new AlertEvaluationRecords.EvaluateRequest(UUID.randomUUID(),equal.id(),0,evidence.id(),now.plusSeconds(90))).state());var rate=rules.create(owner,new AlertRecords.Create(UUID.randomUUID(),"SH600030","DAILY_RISE","2"));var tree=(com.fasterxml.jackson.databind.node.ObjectNode)mapper.valueToTree(evidence);tree.put("changeState","SOURCE_UNAVAILABLE");tree.putNull("previousBackwardClose");tree.putNull("currentBackwardClose");tree.putNull("sourcePayloadHash");org.mockito.Mockito.when(market.read(evidence.id())).thenReturn(mapper.treeToValue(tree,AlertEvidenceClient.Evidence.class));assertEquals("EVIDENCE_UNAVAILABLE",evaluation.evaluate(new AlertEvaluationRecords.EvaluateRequest(UUID.randomUUID(),rate.id(),0,evidence.id(),now.plusSeconds(90))).state());assertEquals(1,restarted.list(owner,1,20,false).total());}
 @Test void concurrentReadCannotSplitOnePageSnapshot()throws Exception{UUID id=message(owner,rule,now);var spy=org.mockito.Mockito.spy(db);var did=new java.util.concurrent.atomic.AtomicBoolean();org.mockito.Mockito.doAnswer(call->{var result=call.callRealMethod();if(did.compareAndSet(false,true)){var pool=java.util.concurrent.Executors.newSingleThreadExecutor();try{pool.submit(()->service.read(owner,id)).get(5,java.util.concurrent.TimeUnit.SECONDS);}finally{pool.shutdownNow();}}return result;}).when(spy).queryForObject(org.mockito.ArgumentMatchers.startsWith("select count(*) from inbox_message m"),org.mockito.ArgumentMatchers.eq(Long.class),org.mockito.ArgumentMatchers.<Object[]>any());var snapshot=new InboxService(spy,mapper,Clock.fixed(now,ZoneOffset.UTC)).list(owner,1,20,true);assertTrue(did.get());assertEquals(1,snapshot.total());assertEquals(1,snapshot.unreadCount());assertEquals(1,snapshot.items().size());assertNull(snapshot.items().get(0).readAt());assertEquals(0,service.unreadCount(owner).unreadCount());}
 @Test void concurrentReversedBatchesHaveNoDeadlockAndOneReadTime()throws Exception{UUID a=message(owner,rule,now),b=message(owner,UUID.randomUUID(),now);var pool=java.util.concurrent.Executors.newFixedThreadPool(2);try{var first=pool.submit(()->service.readBatch(owner,List.of(a,b)));var second=pool.submit(()->service.readBatch(owner,List.of(b,a)));assertEquals(first.get(5,java.util.concurrent.TimeUnit.SECONDS).items().get(0).readAt(),second.get(5,java.util.concurrent.TimeUnit.SECONDS).items().get(1).readAt());assertEquals(0,service.unreadCount(owner).unreadCount());}finally{pool.shutdownNow();}}
 @Test void invalidPagesAndDuplicateOrOversizedBatchesRejected(){for(int[] p:new int[][]{{0,20},{1,0},{1,51},{100001,20}})assertThrows(BusinessException.class,()->service.list(owner,p[0],p[1],false));assertThrows(BusinessException.class,()->service.readBatch(owner,List.of()));assertThrows(BusinessException.class,()->service.readBatch(owner,List.of(rule,rule)));assertThrows(BusinessException.class,()->service.readBatch(owner,java.util.stream.IntStream.range(0,51).mapToObj(i->UUID.randomUUID()).toList()));}
 @Test void historyUsesSavedSnapshotAndHidesForeignOrMissingRules()throws Exception{UUID id=message(owner,rule,now);db.update("insert into alert_user_guard(user_id) values(?)",owner.toString());db.update("insert into alert_rule(rule_id,user_id,instrument_id,condition_code,threshold_value,enabled,revision,effective_after_date,boundary_raw_version,boundary_json,created_at,updated_at) values(?,?,?,'PRICE_ABOVE',999,true,1,'2026-10-09',?,'{}',?,?)",rule.toString(),owner.toString(),"SH600030",UUID.randomUUID().toString(),java.sql.Timestamp.from(now),java.sql.Timestamp.from(now));var saved=service.triggers(owner,rule,1,20).items().get(0);assertEquals(id,saved.id());assertEquals("25.90",saved.threshold());assertEquals("25.91",saved.rawClose());assertNotNull(saved.evidenceId());assertThrows(BusinessException.class,()->service.triggers(other,rule,1,20));assertThrows(BusinessException.class,()->service.triggers(owner,UUID.randomUUID(),1,20));}
}
